<النص البرمجي>
الأسئلة الثابتة = [
  {
    س: ""كم عدد الرؤوس الحربية النووية الموجودة على مستوى العالم اليوم تقريبًا؟""،
    الخيارات: [""~2,500""، ""~12,500""، ""~35,000""، ""~500""]،
    الصحيح: 1،
    ردود الفعل: ""يوجد حوالي 12500 رأس حربي نووي في تسع دول. وقد يؤدي تبادلها على نطاق واسع إلى ""شتاء نووي"" يدوم لسنوات.""
  },
  {
    س: ""في عام 1983، من هو الضابط السوفييتي الذي تجاهل تحذير الأقمار الصناعية من الصواريخ الأمريكية القادمة، مما قد يمنع حربًا نووية؟""،
    يختار: [""ميخائيل جورباتشوف""، ""يوري أندروبوف""، ""ستانيسلاف بيتروف""، ""فاسيلي أرخيبوف""]،
    الصحيح: 2،
    ردود الفعل: ""قرر ستانيسلاف بيتروف عدم الإبلاغ عن الإنذار باعتباره هجومًا حقيقيًا. وربما يكون حكمه في تلك الليلة الواحدة قد أنقذ الحضارة.""
  },
  {
    س: ""في المسارات الحالية، ما هو مستوى ارتفاع درجة الحرارة العالمية الذي سيتجه إليه الكوكب بحلول نهاية القرن؟""،
    الخيارات: [""0.5–1 درجة مئوية""، ""1–1.5 درجة مئوية""، ""2–3 درجة مئوية""، ""5–6 درجة مئوية""]،
    الصحيح: 2،
    ردود الفعل: ""الكوكب في طريقه لارتفاع درجات الحرارة إلى 2-3 درجات مئوية. وبعد 3 درجات مئوية، يمكن أن تؤدي حلقات ردود الفعل الخطيرة - مثل ذوبان التربة الصقيعية وإطلاق غاز الميثان - إلى ارتفاع درجات الحرارة بشكل كبير.""
  },
  {
    س: ""ما الذي يجعل الأسلحة البيولوجية مثيرة للقلق بشكل خاص مقارنة بالأسلحة النووية في العصر الحديث؟""،
    الخيارات: [""إنها أكثر فتكا على الفور""، ""إن حاجز الدخول يتراجع بسرعة بسبب تكنولوجيا المختبرات الرخيصة والذكاء الاصطناعي""، ""إنها تتطلب موارد على مستوى الدولة""، ""من المستحيل اكتشافها""]،
    الصحيح: 1،
ردود الفعل: ""على عكس الأسلحة النووية، أصبحت التكنولوجيا الحيوية أرخص وأكثر سهولة في الوصول إليها. وقد تؤدي أدوات الذكاء الاصطناعي إلى تقليل الخبرة المطلوبة لهندسة مسببات الأمراض الخطيرة.""
  },
  {
    س: ""ما الحدث الذي أثبت لأول مرة أن البشرية قادرة على إبعاد كويكب قادم؟"",
    يختار: [""مهمة عودة عينة Hayabusa2""، ""مهمة DART التابعة لناسا في عام 2022""، ""مهمة هيرا التابعة لوكالة الفضاء الأوروبية في عام 2024""، ""استجابة نيزك تشيليابينسك في عام 2013""]،
    الصحيح: 1،
    ردود الفعل: ""نجحت مهمة DART التابعة لوكالة ناسا في عام 2022 في تغيير مدار الكويكب عن طريق صدم مركبة فضائية فيه - وهو أول اختبار حقيقي للدفاع الكوكبي للبشرية.""
  },
  {
    س: ""أي مما يلي يعد مثالاً على استخدام الذكاء الاصطناعي كأداة دفاعية ضد التهديدات الوجودية؟""،
    الخيارات: [""توليد دعاية عميقة التزييف""، ""تسريع اكتشاف الأدوية والكشف عن الأوبئة""، ""تصميم أسلحة مستقلة""، ""خفض حاجز هندسة مسببات الأمراض""]،
    الصحيح: 1،
    ردود الفعل: ""يتم استخدام الذكاء الاصطناعي لتسريع اكتشاف الأدوية، وتحسين الكشف عن الأوبئة من خلال مراقبة الأمراض العالمية، وتعزيز النمذجة المناخية - وجميعها تطبيقات دفاعية.""
  },
  {
    س: ""ما هو ""الذكاء الاصطناعي المنحرف"" في سياق المخاطر الوجودية؟""،
    يختار: [""الذكاء الاصطناعي المتحيز ضد الأقليات""، ""الذكاء الاصطناعي الذي يتعطل أو يتعطل بشكل متكرر""، ""الذكاء الاصطناعي الذي يسعى إلى تحقيق أهداف تتعارض بمهارة مع القيم الإنسانية""، ""الذكاء الاصطناعي الذي تستخدمه الحكومات المعادية""]،
    الصحيح: 2،
    ردود الفعل: ""يشير الاختلال إلى خطر سعي الذكاء الاصطناعي المتقدم إلى تحقيق الأهداف بطرق كارثية بالنسبة للبشر - حتى عندما يُعطى أهدافًا تبدو بسيطة - لأن قيمه لا تتماشى بشكل عميق مع قيمنا.""
  },
  {
    س: ""يصف المقال ""الشتاء النووي"" كنتيجة لحرب نووية واسعة النطاق. ما أسبابه؟"",
    الخيارات: [""تسمم المحاصيل بالإشعاع""، ""السخام الناتج عن العواصف النارية الذي يحجب ضوء الشمس لسنوات""، ""الأسلحة الكيميائية تلوث المياه الجوفية""، ""النبضات الكهرومغناطيسية توقف الزراعة""]،
    الصحيح: 1،
    ردود الفعل: ""العواصف النارية الهائلة الناجمة عن الانفجارات النووية تضخ السخام في طبقة الستراتوسفير، مما يحجب ضوء الشمس لسنوات وينهار الزراعة على مستوى العالم - مما قد يؤدي إلى مقتل المليارات من خلال المجاعة.""
  },
  {
    س: ""كم انخفضت تكاليف الطاقة الشمسية في العقد الماضي، وفقًا للمقالة؟"",
    الخيارات: [""حوالي 30%""، ""حوالي 50%""، ""أكثر من 70%""، ""أكثر من 90%""]،
    الصحيح: 3،
    ردود الفعل: ""لقد انخفضت تكاليف الطاقة الشمسية بنسبة تزيد عن 90% في العقد الماضي - وهو تحول ملحوظ يجعل التحول إلى الطاقة النظيفة قابلاً للتطبيق اقتصاديًا على نطاق واسع.""
  },
  {
    س: ""وفقًا للمقالة، ما هي الحجة الأساسية للتفاؤل بشأن قدرة البشرية على النجاة من التهديدات الوجودية؟""،
    يختار: [""سوف يحل الذكاء الاصطناعي جميع المشاكل تلقائيًا""، ""لقد تجنبنا الحرب النووية، وقضينا على الجدري، وبدأنا في معالجة المناخ - مما يظهر القدرة الجماعية على إدارة التهديدات""، ""تمتلك الحكومات الآن أنظمة تنسيق مثالية""، ""المخاطر الوجودية غير مرجحة جدًا من الناحية الإحصائية""]،
    الصحيح: 1،
    ردود الفعل: ""يشير المقال إلى انتصارات تاريخية حقيقية: تجنب الحرب النووية خلال الحرب الباردة، والقضاء على الجدري، وبدء تحول الطاقة - وهو دليل على أن الإبداع البشري والتعاون، في أفضل حالاتهما، أمران رائعان.""
  }
]

