<div class=""quiz-wrap"">
  <h1>🌍 End of the World Quiz</h1>
  <div class=""progress-bar-bg""><div class=""progress-bar-fill"" id=""progress"" style=""width:0%""></div></div>
  <div id=""quiz-area""></div>
</div>

<script>
const questions = [
  {
    q: ""Approximately how many nuclear warheads exist globally today?"",
    opts: [""~2,500"", ""~12,500"", ""~35,000"", ""~500""],
    correct: 1,
    feedback: ""Around 12,500 nuclear warheads exist across nine countries. A large-scale exchange could trigger a 'nuclear winter' lasting years.""
  },
  {
    q: ""In 1983, which Soviet officer famously ignored a satellite warning of incoming US missiles, potentially preventing nuclear war?"",
    opts: [""Mikhail Gorbachev"", ""Yuri Andropov"", ""Stanislav Petrov"", ""Vasily Arkhipov""],
    correct: 2,
    feedback: ""Stanislav Petrov decided not to report the alarm as a genuine attack. His judgment on that single night may have saved civilization.""
  },
  {
    q: ""At current trajectories, what level of global temperature rise is the planet on course for by end of century?"",
    opts: [""0.5–1°C"", ""1–1.5°C"", ""2–3°C"", ""5–6°C""],
    correct: 2,
    feedback: ""The planet is on course for 2–3°C. Beyond 3°C, dangerous feedback loops — like melting permafrost releasing methane — could push warming much higher.""
  },
  {
    q: ""What makes bioweapons particularly alarming compared to nuclear weapons in the modern era?"",
    opts: [""They are more immediately lethal"", ""The barrier to entry is falling rapidly due to cheaper lab tech and AI"", ""They require state-level resources"", ""They are impossible to detect""],
    correct: 1,
feedback: ""Unlike nuclear weapons, biotechnology is becoming cheaper and more accessible. AI tools may further lower the expertise required to engineer dangerous pathogens.""
  },
  {
    q: ""What event proved for the first time that humanity can deflect an incoming asteroid?"",
    opts: [""Hayabusa2 sample return mission"", ""NASA's DART mission in 2022"", ""ESA's Hera mission in 2024"", ""The Chelyabinsk meteor response in 2013""],
    correct: 1,
    feedback: ""NASA's DART mission in 2022 successfully changed an asteroid's orbit by ramming a spacecraft into it — humanity's first real planetary defense test.""
  },
  {
    q: ""Which of these is an example of AI being used as a DEFENSIVE tool against existential threats?"",
    opts: [""Generating deepfake propaganda"", ""Accelerating drug discovery and pandemic detection"", ""Designing autonomous weapons"", ""Lowering the barrier to engineer pathogens""],
    correct: 1,
    feedback: ""AI is being used to accelerate drug discovery, improve pandemic detection through global disease surveillance, and enhance climate modeling — all defensive applications.""
  },
  {
    q: ""What is 'misaligned AI' in the context of existential risk?"",
    opts: [""AI that is biased against minority groups"", ""AI that crashes or malfunctions frequently"", ""AI that pursues goals subtly at odds with human values"", ""AI that is used by hostile governments""],
    correct: 2,
    feedback: ""Misalignment refers to the risk that advanced AI pursues objectives in ways that are catastrophic for humans — even when given seemingly simple goals — because its values aren't deeply aligned with ours.""
  },
  {
    q: ""The article describes 'nuclear winter' as a consequence of large-scale nuclear war. What causes it?"",
    opts: [""Radiation poisoning of crops"", ""Soot from firestorms blocking sunlight for years"", ""Chemical weapons contaminating groundwater"", ""Electromagnetic pulses shutting down agriculture""],
    correct: 1,
    feedback: ""Massive firestorms from nuclear explosions inject soot into the stratosphere, blocking sunlight for years and collapsing agriculture globally — potentially killing billions through famine.""
  },
  {
    q: ""How much have solar power costs fallen in the last decade, according to the article?"",
    opts: [""Around 30%"", ""Around 50%"", ""Over 70%"", ""Over 90%""],
    correct: 3,
    feedback: ""Solar power costs have fallen over 90% in the last decade — a remarkable shift that is making the clean energy transition economically viable at scale.""
  },
  {
    q: ""According to the article, what is the core argument for optimism about humanity's ability to survive existential threats?"",
    opts: [""AI will solve all problems automatically"", ""We have avoided nuclear war, eliminated smallpox, and begun addressing climate — showing collective capacity to manage threats"", ""Governments now have perfect coordination systems"", ""Existential risks are statistically very unlikely""],
    correct: 1,
    feedback: ""The article points to real historical wins: avoiding nuclear war during the Cold War, eliminating smallpox, and beginning the energy transition — evidence that human ingenuity and cooperation, at their best, are remarkable.""
  }
]

