  <div class=""progress-bar-bg""><div class=""progress-bar-fill"" id=""progress"" style=""width:0%""></div></div>
  <div id=""quiz-area""></div>
</div>

<скрипт>
константные вопросы = [
  {
    вопрос: «Сколько примерно ядерных боеголовок существует сегодня в мире?»,
    варианты: [""~2500"", ""~12500"", ""~35000"", ""~500""],
    правильно: 1,
    обратная связь: «В девяти странах имеется около 12 500 ядерных боеголовок. Крупномасштабный обмен может спровоцировать «ядерную зиму», которая продлится несколько лет».
  },
  {
    вопрос: «Какой советский офицер в 1983 году проигнорировал спутниковое предупреждение о приближающихся американских ракетах, потенциально предотвращающих ядерную войну?»,
    варианты: [""Михаил Горбачев"", ""Юрий Андропов"", ""Станислав Петров"", ""Василий Архипов""],
    правильно: 2,
    отзыв: «Станислав Петров решил не сообщать о тревоге как о реальном нападении. Его решение в ту единственную ночь, возможно, спасло цивилизацию».
  },
  {
    вопрос: «При нынешних траекториях, какой уровень глобального повышения температуры ожидает планету к концу столетия?»,
    варианты: [""0,5–1°C"", ""1–1,5°C"", ""2–3°C"", ""5–6°C""],
    правильно: 2,
    обратная связь: «Планета движется к потеплению на 2–3°C. За пределами 3°C опасные петли обратной связи — такие как таяние вечной мерзлоты с выделением метана — могут значительно ускорить потепление».
  },
  {
    вопрос: «Что делает биологическое оружие особенно тревожным по сравнению с ядерным оружием в современную эпоху?»,
    opts: [""Они более смертоносны"", ""Барьер для входа быстро падает из-за удешевления лабораторных технологий и искусственного интеллекта"", ""Они требуют ресурсов государственного уровня"", ""Их невозможно обнаружить""],
    правильно: 1,
отзыв: «В отличие от ядерного оружия, биотехнологии становятся дешевле и доступнее. Инструменты искусственного интеллекта могут еще больше снизить уровень знаний, необходимых для создания опасных патогенов».
  },
  {
    вопрос: «Какое событие впервые доказало, что человечество может отклонить приближающийся астероид?»,
    opts: [""Миссия по возвращению образцов Hayabusa2"", ""Миссия НАСА DART в 2022 году"", ""Миссия ЕКА Гера в 2024 году"", ""Ответ на Челябинский метеорит в 2013 году""],
    правильно: 1,
    отзыв: «Миссия НАСА DART в 2022 году успешно изменила орбиту астероида, врезавшись в него космическим кораблем — первое настоящее испытание человечества на планетарную защиту».
  },
  {
    вопрос: «Что из этого является примером использования ИИ в качестве ЗАЩИТНОГО инструмента от экзистенциальных угроз?»,
    варианты: [«Создание дипфейковой пропаганды», «Ускорение открытия лекарств и выявления пандемий», «Разработка автономного оружия», «Снижение барьера для создания патогенов»],
    правильно: 1,
    обратная связь: «ИИ используется для ускорения разработки лекарств, улучшения обнаружения пандемий посредством глобального наблюдения за болезнями и улучшения моделирования климата — все это защитные приложения».
  },
  {
    вопрос: «Что такое «несогласованный ИИ» в контексте экзистенциального риска?»,
    opts: [«ИИ, который предвзято относится к группам меньшинств», «ИИ, который часто дает сбой или дает сбой», «ИИ, который преследует цели, слегка противоречащие человеческим ценностям», «ИИ, который используется враждебными правительствами»],
    правильно: 2,
    обратная связь: «Несогласованность означает риск того, что продвинутый ИИ преследует цели катастрофическими для людей способами — даже если перед ними стоят, казалось бы, простые цели — потому что его ценности не глубоко совпадают с нашими».
  },
  {
    в: «В статье описывается «ядерная зима» как следствие крупномасштабной ядерной войны. Что ее вызывает?»,
    варианты: [«Радиационное отравление сельскохозяйственных культур», «Сажа от огненных бурь на годы блокирует солнечный свет», «Химическое оружие загрязняет грунтовые воды», «Электромагнитные импульсы останавливают сельское хозяйство»],
    правильно: 1,
    отзыв: «Мощные огненные бури от ядерных взрывов выбрасывают сажу в стратосферу, блокируя солнечный свет на годы и разрушая сельское хозяйство во всем мире, потенциально убивая миллиарды людей от голода».
  },
  {
    вопрос: «Согласно статье, насколько упали затраты на солнечную энергию за последнее десятилетие?»,
    opts: [""Около 30%"", ""Около 50%"", ""Более 70%"", ""Более 90%""],
    правильно: 3,
    отзыв: «За последнее десятилетие стоимость солнечной энергии упала более чем на 90% — замечательный сдвиг, который делает переход к экологически чистой энергии экономически жизнеспособным в больших масштабах».
  },
  {
    вопрос: «Согласно статье, каков основной аргумент в пользу оптимизма относительно способности человечества пережить экзистенциальные угрозы?»,
    opts: [""ИИ решит все проблемы автоматически"", ""Мы избежали ядерной войны, ликвидировали оспа и начали бороться с климатом, продемонстрировав коллективную способность справляться с угрозами"", ""У правительств теперь есть совершенные системы координации"", ""Экзистенциальные риски статистически очень маловероятны""],
    правильно: 1,
    отзыв: «В статье указываются на реальные исторические победы: предотвращение ядерной войны во время холодной войны, ликвидация оспы и начало энергетического перехода — свидетельство того, что человеческая изобретательность и сотрудничество в своих лучших проявлениях замечательны».
  }
]

