<脚本>
常量问题 = [
  {
    问：“当今全球大约有多少核弹头？”,
    选择：[“〜2,500”，“〜12,500”，“〜35,000”，“〜500”]，
    正确：1、
    反馈：“九个国家约有 12,500 枚核弹头。大规模交换可能引发持续数年的‘核冬天’。”
  },
  {
    问：“1983 年，哪位苏联军官因无视美国导弹来袭的卫星警告而闻名，这可能会阻止核战争？”，
    选择：[“米哈伊尔·戈尔巴乔夫”、“尤里·安德罗波夫”、“斯坦尼斯拉夫·彼得罗夫”、“瓦西里·阿尔希波夫”]，
    正确：2，
    反馈：“斯坦尼斯拉夫·彼得罗夫决定不将警报报告为真正的攻击。他在那一晚的判断可能拯救了文明。”
  },
  {
    问：“按照目前的轨迹，到本世纪末，地球的全球气温将上升到什么水平？”，
    选择：[“0.5–1°C”、“1–1.5°C”、“2–3°C”、“5–6°C”]、
    正确：2，
    反馈：“地球的气温正在上升 2°C 至 3°C。超过 3°C，危险的反馈循环（例如永久冻土融化释放甲烷）可能会进一步加剧变暖。”
  },
  {
    问：“与现代的核武器相比，是什么让生物武器特别令人震惊？”，
    选择：[“它们更直接致命”，“由于更便宜的实验室技术和人工智能，进入壁垒正在迅速下降”，“它们需要国家级资源”，“它们不可能被发现”]，
    正确：1、
反馈：“与核武器不同，生物技术变得越来越便宜且更容易获得。人工智能工具可能会进一步降低设计危险病原体所需的专业知识。”
  },
  {
    q：“什么事件首次证明人类可以偏转即将到来的小行星？”，
    opts: [""Hayabusa2 样本返回任务""、""NASA 2022 年 DART 任务""、""ESA 2024 年 Hera 任务""、""2013 年车里雅宾斯克流星响应""],
    正确：1、
    反馈：“NASA 2022 年的 DART 任务通过撞击航天器成功改变了小行星的轨道，这是人类第一次真正的行星防御测试。”
  },
  {
    q：“以下哪一个是人工智能被用作防御现有威胁的防御工具的例子？”，
    opts: [“生成深度伪造宣传”、“加速药物发现和流行病检测”、“设计自主武器”、“降低工程病原体的障碍”]，
    正确：1、
    反馈：“人工智能正在被用来加速药物发现，通过全球疾病监测改善大流行病检测，并增强气候建模——所有防御性应用。”
  },
  {
    问：“在存在风险的背景下，什么是‘错位人工智能’？”，
    选择：[“对少数群体有偏见的人工智能”，“经常崩溃或故障的人工智能”，“追求与人类价值观微妙不一致的目标的人工智能”，“被敌对政府使用的人工智能”]，
    正确：2，
    反馈：“错位是指先进人工智能以对人类来说是灾难性的方式追求目标的风险——即使目标看似简单——因为它的价值观与我们的价值观不一致。”
  },
  {
    q：“文章将‘核冬天’描述为大规模核战争的后果。是什么原因造成的？”,
    选择：[“农作物的辐射中毒”、“大火造成的烟尘阻挡阳光多年”、“化学武器污染地下水”、“电磁脉冲导致农业停顿”]，
    正确：1、
    反馈：“核爆炸引发的大规模火灾风暴将烟尘注入平流层，数年阻挡阳光照射，导致全球农业崩溃，可能导致数十亿人因饥荒而死亡。”
  },
  {
    问：“根据这篇文章，过去十年太阳能发电成本下降了多少？”,
    opts: [""约30%"", ""约50%"", ""超过70%"", ""超过90%""],
    正确：3，
    反馈：“在过去十年中，太阳能成本下降了 90% 以上，这是一个显着的转变，使清洁能源转型在经济上大规模可行。”
  },
  {
    q：“根据这篇文章，对人类生存威胁的能力持乐观态度的核心论据是什么？”，
    选择：[“人工智能将自动解决所有问题”，“我们已经避免了核战争，消灭了天花，并开始解决气候问题——显示出管理威胁的集体能力”，“政府现在拥有完善的协调系统”，“从统计角度来看，存在风险的可能性很小”]，
    正确：1、
    反馈：“文章指出了真正的历史性胜利：避免冷战期间的核战争、消除天花以及开始能源转型——这证明人类的聪明才智和合作在最好的情况下是非凡的。”
  }
]

